//go:build arm64

package floats

import "unsafe"

// The NEON kernel of PSMixPlan32.Run (psmix32.go), generated by go-asmgen
// (psmix32_arm64_gen.go) into psmix32_arm64.s: every run of a slot in one call, four rows per
// vector, the short runs and the tails by a full vector that may touch up to 3 rows past a run
// (inside the 7 that the contract of psmix32.go allows and Run proved). NEON is the ARMv8-A
// baseline: no gate. Every operand is passed as a pointer to its first element; a source that
// no run uses is passed as the first plane that does (never read). No kernel keeps a pointer:
// go:noescape.
//
//go:noescape
func psMix32NEON(nruns int, runs *psMixRun32, gains, tg, sre, sim, lre, lim, rre, rim, d0re, d0im, d1re, d1im, d2re, d2im *float32)

func psMix32(p *PSMixPlan32, gains, tg []float32, s Split32, d *[3]Split32, l, r Split32) {
	var dp [3]Split32
	for q := range dp {
		dp[q] = d[q]
		if p.srcEnd[q] == 0 {
			dp[q] = s
		}
	}
	psMix32NEON(len(p.runs), unsafe.SliceData(p.runs), &gains[0], &tg[0],
		&s.Re[0], &s.Im[0], &l.Re[0], &l.Im[0], &r.Re[0], &r.Im[0],
		&dp[0].Re[0], &dp[0].Im[0], &dp[1].Re[0], &dp[1].Im[0], &dp[2].Re[0], &dp[2].Im[0])
}
